  function moduleDescription(type){const map={properties:["الوحدات والأسعار والصور والتوفر","Units, pricing, media and availability"],owners:["ملفات الملاك والكشوف والمستحقات","Owner profiles, statements and dues"],clients:["طلبات العملاء والميزانيات والمتابعة","Leads, requirements, budgets and follow-up"],deals:["المعاينات والعروض والتفاوض والإغلاق","Viewings, offers, negotiation and closing"],contracts:["البيع والإيجار والتجديد والتنبيهات","Sales, leases, renewals and alerts"],payments:["التحصيل والشيكات والعمولات والمتأخرات","Collections, cheques, commissions and arrears"],maintenance:["الطلبات والمقاولون والتكلفة والتنفيذ","Requests, contractors, costs and progress"],employees:["الوكلاء والأدوار والصلاحيات والأداء","Agents, roles, permissions and performance"],reports:["الإشغال والإيرادات والصفقات والأداء","Occupancy, revenue, deals and performance"],settings:["بيانات المكتب والعمولات والتنبيهات","Office profile, commissions and alerts"]};return t(...(map[type]||["",""]))}

  function renderProperties(){const items=data.properties.filter(matches);return hero(t("محفظة العقارات","PROPERTY PORTFOLIO"),t("العقارات والوحدات","Properties & Units"),t("إدارة جميع الوحدات المعروضة للبيع أو الإيجار ومتابعة حالتها وأسعارها.","Manage all properties for sale or rent, including status and pricing."),"properties",t("إضافة عقار","Add Property"))+`<div class="re-kpi-grid">${kpi("properties",t("كل العقارات","All Properties"),data.properties.length,t("إجمالي الوحدات المسجلة","Total registered units"))}${kpi("properties",t("المتاحة","Available"),data.properties.filter(x=>x.status==="available").length,t("جاهزة للتسويق","Ready to market"))}${kpi("contracts",t("المؤجرة","Rented"),data.properties.filter(x=>x.status==="rented").length,t("مرتبطة بعقود سارية","Linked to active contracts"),"blue")}${kpi("deals",t("القيمة الإجمالية","Total Value"),money(data.properties.reduce((s,x)=>s+Number(x.price||0),0)),t("قيمة المحفظة المعروضة","Listed portfolio value"),"amber")}</div>${sectionHead(t("قائمة العقارات","Property List"),t("البحث والتصفية حسب حالة الوحدة","Search and filter by property status"),"properties",t("عقار جديد","New Property"))}${toolbar(["available","rented","reserved","sold"])}<div class="re-property-grid">${items.map(x=>`<article class="re-property-card"><div class="re-property-cover">${svg("properties")}${badge(x.status)}</div><div class="re-property-body"><h3>${esc(x.title)}</h3><p>${esc(x.location)} · ${esc(x.unit)}</p><div class="re-property-meta"><span>🛏 ${esc(x.beds)}</span><span>🚿 ${esc(x.baths)}</span><span>▱ ${esc(x.size)} ${t("قدم²","ft²")}</span><span>${esc(x.purpose)}</span></div><div class="re-property-price"><strong>${money(x.price)}</strong>${actions("properties",x.id)}</div></div></article>`).join("")||empty()}</div>`}
  function renderOwners(){const items=data.owners.filter(matches);return hero(t("إدارة الملاك","OWNER RELATIONS"),t("الملاك","Property Owners"),t("حفظ ملفات الملاك وربط كل مالك بعقاراته وعقوده ومستحقاته.","Keep owner profiles connected to their properties, contracts and balances."),"owners",t("إضافة مالك","Add Owner"))+`${sectionHead(t("ملفات الملاك","Owner Profiles"),t("بيانات الاتصال والعقارات والأرصدة","Contact details, properties and balances"),"owners",t("مالك جديد","New Owner"))}${toolbar()}<div class="re-people-grid">${items.map(x=>{const count=data.properties.filter(p=>p.ownerId===x.id).length;return`<article class="re-person-card"><span class="re-avatar">${esc(x.name.slice(0,1))}</span><h3>${esc(x.name)}</h3><p>${esc(x.phone)} · ${esc(x.email||"—")}</p><div class="re-person-stats"><span>${t("العقارات","Properties")}<strong>${count}</strong></span><span>${t("الرصيد","Balance")}<strong>${money(x.balance)}</strong></span></div><div class="re-modal-actions">${actions("owners",x.id)}</div></article>`}).join("")||empty()}</div>`}
