  function renderDeals(){const stages=["new","visit","offer","negotiation"],items=data.deals.filter(matches);return hero(t("مسار الصفقات","DEAL PIPELINE"),t("الصفقات والمتابعة","Deals & Follow-Up"),t("تابع كل فرصة من الطلب الأول وحتى العرض والتفاوض وإغلاق الصفقة.","Track every opportunity from the first inquiry through offer, negotiation and closing."),"deals",t("إضافة صفقة","Add Deal"))+`${sectionHead(t("مسار المبيعات العقارية","Real Estate Sales Pipeline"),t("توزيع الصفقات حسب المرحلة الحالية","Deals grouped by current stage"),"deals",t("صفقة جديدة","New Deal"))}${toolbar()}<div class="re-pipeline">${stages.map(stage=>`<section class="re-pipeline-col"><div class="re-pipeline-head"><strong>${t(...statusText[stage])}</strong><span class="re-badge">${items.filter(x=>x.status===stage).length}</span></div>${items.filter(x=>x.status===stage).map(x=>`<article class="re-lead-card"><h4>${esc(display("clients",x.clientId))}</h4><p>${esc(display("properties",x.propertyId))}<br>${esc(x.type)} · ${money(x.value)}</p><footer><span>${esc(x.nextDate||"—")}</span>${actions("deals",x.id)}</footer></article>`).join("")||`<div class="re-empty"><p>${t("لا توجد صفقات في هذه المرحلة","No deals in this stage")}</p></div>`}</section>`).join("")}</div>`}
