  function renderPage(){const content=document.getElementById("reContent");const map={dashboard:renderDashboard,properties:renderProperties,owners:renderOwners,clients:renderClients,deals:renderDeals,contracts:renderContracts,payments:renderPayments,maintenance:renderMaintenance,employees:renderEmployees,reports:renderReports,settings:renderSettings};content.innerHTML=(map[page]||renderDashboard)();bindPage()}
  function bindPage(){
    document.querySelectorAll("[data-open-form]").forEach(b=>b.addEventListener("click",()=>openForm(b.dataset.openForm)));
    document.querySelectorAll("[data-edit-type]").forEach(b=>b.addEventListener("click",()=>openForm(b.dataset.editType,b.dataset.editId)));
    document.querySelectorAll("[data-delete-type]").forEach(b=>b.addEventListener("click",()=>confirmDelete(b.dataset.deleteType,b.dataset.deleteId)));
    const search=document.getElementById("reSearch");if(search)search.addEventListener("input",()=>{filters.search=search.value;renderPage()});
    const status=document.getElementById("reStatus");if(status)status.addEventListener("change",()=>{filters.status=status.value;renderPage()});
    const settingsForm=document.getElementById("reSettingsForm");if(settingsForm)settingsForm.addEventListener("submit",saveSettings);
    document.querySelectorAll("[data-setting-toggle]").forEach(b=>b.addEventListener("click",()=>{const key=b.dataset.settingToggle;data.settings[key]=!data.settings[key];save();renderPage();toast(t("تم تحديث إعدادات التنبيهات","Notification settings updated"))}));
    const lang=document.getElementById("reSettingLanguage");if(lang)lang.addEventListener("click",()=>setLanguage(language==="ar"?"en":"ar"));
    const settingTheme=document.getElementById("reSettingTheme");if(settingTheme)settingTheme.addEventListener("click",toggleTheme);
    const exp=document.getElementById("reExport");if(exp)exp.addEventListener("click",exportData);
    const reset=document.getElementById("reReset");if(reset)reset.addEventListener("click",()=>openConfirm(t("إعادة البيانات التجريبية؟","Restore demo data?"),t("سيتم استبدال البيانات الحالية بالنسخة التجريبية.","Current data will be replaced with the demo data."),()=>{data=seed();save();renderPage();toast(t("تمت إعادة البيانات التجريبية","Demo data restored"))}));
  }

